using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public sealed class EvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = CreateReportingConfiguration();
    }

    [AssemblyCleanup]
    public static async Task Cleanup()
    {
        if (s_reportingConfiguration is not null)
        {
            await s_reportingConfiguration.DisposeAsync();
        }
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(
            Path.GetDirectoryName(typeof(EvaluationTests).Assembly.Location)!,
            "evaluation-report");

        return DiskBasedReportingConfiguration.Create(storageRootPath: path);
    }

    [TestMethod]
    public async Task Chat_responds_relevantly()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_relevantly));

        var chatClient = scenario.GetChatClient(CreateChatClient());
        var evaluators = new IEvaluator[] { new RelevancyEvaluator() };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var result = await scenario.EvaluateAsync(
            messages,
            evaluators);

        scenario.RecordResult(result);
    }

    [TestMethod]
    public async Task Chat_responds_coherently()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_coherently));

        var chatClient = scenario.GetChatClient(CreateChatClient());
        var evaluators = new IEvaluator[] { new CoherenceEvaluator() };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain how photosynthesis works in three sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var result = await scenario.EvaluateAsync(
            messages,
            evaluators);

        scenario.RecordResult(result);
    }

    [TestMethod]
    public async Task Chat_responds_fluently()
    {
        await using var scenario =
            await s_reportingConfiguration!.CreateScenarioRunAsync(
                scenarioName: nameof(Chat_responds_fluently));

        var chatClient = scenario.GetChatClient(CreateChatClient());
        var evaluators = new IEvaluator[] { new FluencyEvaluator() };

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Write a brief summary of the benefits of unit testing.")
        };

        var response = await chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        var result = await scenario.EvaluateAsync(
            messages,
            evaluators);

        scenario.RecordResult(result);
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("CHAT_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("CHAT_API_KEY") ?? "";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o")
            .AsIChatClient();
    }
}

